    dihedral_counter = 0
    for key, val in self.order_dict.items():
        if self.mol_dic[val]["Dihedrals"].size != 0:
            self.mol_dic[val]["Dihedrals"][:, -4:] = (
                self.mol_dic[val]["Dihedrals"][:, -4:] + dihedral_counter
